                                            </div>
                                            <div className="text-right">
                                                <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mb-0.5">Progress</p>
                                                <p className="text-xs font-bold text-gray-900">{currentCount} / {prog.stickersRequired}</p>
                                            </div>
                                        </div>
                                    </div>
